# SDDS-FINAI SDDS-FINAI Набор компонентов и утилит для создания web-приложений на базе  ReactJS . ## Использование Использование Библиотека реализована с помощью: typescript styled-components  (рекомендуем использовать версию  `5.3.1` ) Однако их использование  необязательно ! ### Установка зависимостей Установка зависимостей :::info
Убедитесь, что у вас установлен ReactJS!
::: ```bash
$ npm install --save @salutejs/sdds-finai @salutejs/sdds-themes
```

Для работы со  `styled-components` , необходимо установить ```bash
$ npm install --save styled-components@5.3.1
```

### Использование компонентов Использование компонентов Все компоненты доступны напрямую из пакета ```jsx
import styled from 'styled-components';
import { Button } from '@salutejs/sdds-finai';
import { textAccent } from '@salutejs/sdds-themes/tokens';

export const App = () => {
    const StyledP = styled.p`
        color: ${textAccent};
    `;

    return (
        <>
            <Button>Hello, SDDS-FinAI!</Button>

            <StyledP>
                Token usage example
            </StyledP>
        </>
    );
};
```

## Подключение шрифтов Подключение шрифтов Типографическая система основана на фирменных шрифтах. Для того чтобы шрифт было удобно поставлять в web-приложения, шрифт был загружен на  CDN . Для использования типографической системы необходимо загрузить три  `css`  файла в зависимости от используемых шрифтов в теме.

## Переключение тем Переключение тем

```jsx
import React, { useState } from 'react';
import { createGlobalStyle } from 'styled-components';

import { Switch } from '@salutejs/sdds-finai';
import { sdds_finai__light, sdds_finai__dark } from '@salutejs/sdds-themes';

const LightTheme = createGlobalStyle(sdds_finai__light);
const DarkTheme = createGlobalStyle(sdds_finai__dark);

const App = () => {
    const [theme, setTheme] = useState('light');

    return (
        <>
            {theme === 'light' ? <LightTheme /> : <DarkTheme />}

            <div className="wrapper">
                <Switch
                    label={`app theme: ${theme}`}
                    onChange={() => {
                        setTheme((theme) => (theme === 'light' ? 'dark' : 'light'));
                    }}
                />
            </div>
        </>
    );
};

export default App;
```

## Подключение темы Подключение темы :::info
Точкой входа является корень приложения: Если вы используете  Create React App , делайте вызов внутри  `src/index.tsx` . Если вы используете  Next.js , создайте файл  `pages/_app.tsx`  и подключите стили в нем.
:::

```jsx
import React from 'react';
import { createGlobalStyle } from 'styled-components';
import { Button, BodyL } from '@salutejs/sdds-finai';
import { sdds_finai__light } from '@salutejs/sdds-themes';

const Theme = createGlobalStyle(sdds_finai__light);

const App = () => {
    return (
        <>
            <Theme />
            <BodyL>Hello world</BodyL>
            <Button text="This is themed button" />
        </>
    );
};

export default App;
```

:::info
Если в качестве основы web-приложения вы используете Next, вам необходимо изменить файл  `./pages/index.html` .
::: ```tsx
